math.eq{font-size:1.15em;direction:ltr;unicode-bidi:isolate;margin:0 2px}math.eq mfrac{font-size:1em}
.qimg{display:block;max-width:100%;width:auto;max-height:340px;border-radius:12px;border:2px solid var(--line);margin:8px 0;background:#fff}
.oimg{display:block;max-width:100%;max-height:150px;border-radius:10px;margin:2px 0 4px}
.eqbar{display:flex;flex-wrap:wrap;gap:4px;margin:4px 0}.eqbar button{font:700 15px Cairo,sans-serif;min-width:38px;min-height:34px;border:1.5px solid #9fb7cf;background:#f3f8fd;border-radius:9px;cursor:pointer;padding:0 8px;color:#0d2c4a}
.eqpv{font-size:16px;color:#264;min-height:0}.eqpv:not(:empty){padding:4px 8px;background:#f2fbf0;border-radius:8px;margin:2px 0 6px}
